'use strict';
const KEY='tobin-skidoo-garage-v1';
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=x=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',maximumFractionDigits:0}).format(Number(x)||0);
const uid=()=>globalThis.crypto?.randomUUID?.()||Date.now().toString(36)+Math.random().toString(36).slice(2);
const today=()=>new Date().toLocaleDateString('en-CA');
const dateLabel=d=>new Date(d+'T12:00:00').toLocaleDateString('en-US',{month:'short',day:'numeric',year:'numeric'});
const CATEGORIES=['Engine & ignition','Fuel system','Chaincase & drive','Track & suspension','Electrical','Body & cosmetics','Cables & brakes','Research & setup'];
const STATUSES=['Inspect','Needed','Ordered','On hand','Installed','Not required'];
const NAMES={early:'Early Ski-Doo',eight:'1968 Olympique 300 E'};
const source68='https://www.vintagesnow.com/Ski-Doo_files/1968%20Ski-doo%20Parts%20List%20.pdf';
const sourceEarly='https://vintagesnow.com/Ski-Doo_files/1960-1965%20Ski-doo%20Parts%20List.pdf';
const sourceCodes='https://www.trailz.net/pub/Snowmobiles/SKIDOO/1996-1997/1997/MSPE_A97.PDF';
const baseParts=[
 ['Crankshaft seals & engine leak test','Engine & ignition','High','Identify installed engine. Pressure/vacuum test using the correct service procedure before deciding on seals.'],
 ['Piston, rings & cylinder inspection','Engine & ignition','High','Measure bore, wear and clearances before selecting standard or oversize parts.'],
 ['Wrist pin & small-end bearing','Engine & ignition','Normal','Inspect during engine assessment; match to measured piston and installed engine.'],
 ['Engine gasket set','Engine & ignition','High','Select by installed engine and planned disassembly.'],
 ['Spark plug & ignition lead','Engine & ignition','High','Confirm specified plug and gap from the applicable manual.'],
 ['Points, condenser & ignition coil','Engine & ignition','High','Inspect and test ignition; replace failed or worn components.'],
 ['Recoil rope, spring & pawls','Engine & ignition','Normal','Inspect recoil action and engagement before ordering.'],
 ['Carburetor service kit','Fuel system','High','Read carburetor model stamping first. Select the correct diaphragm/gasket kit; do not assume a float carburetor.'],
 ['Fuel lines, filter & fittings','Fuel system','High','Inspect all lines and connections; confirm compatible material, diameter and routing.'],
 ['Fuel tank, cap & gasket','Fuel system','High','Inspect for corrosion and leaks; clean tank. Decide on repair or replacement after inspection.'],
 ['Drive belt','Chaincase & drive','High','Confirm exact belt specification for installed drive components.'],
 ['Drive & driven clutch service','Chaincase & drive','Normal','Inspect sheaves, bushings and springs; identify actual clutch assemblies.'],
 ['Chaincase seals & cover gasket','Chaincase & drive','High','Inspect leaks, bearings and oil condition. Confirm lubricant and quantity in applicable manual.'],
 ['Drive chain, sprockets & bearings','Chaincase & drive','Normal','Inspect condition and tension; match sprocket and chain dimensions before ordering.'],
 ['Bogie wheels, bearings & axles','Track & suspension','High','Count installed wheels and inspect each wheel, bearing and axle. Record actual replacement quantity.'],
 ['Suspension springs & hardware','Track & suspension','Normal','Inspect spring condition, alignment and fasteners.'],
 ['Track & drive sprockets','Track & suspension','High','Inspect rubber, drive engagement and damage; measure dimensions before ordering.'],
 ['Skis, wear bars & pivot hardware','Track & suspension','High','Inspect ski steel, wear bars and pivots; confirm mounting pattern.'],
 ['Steering linkage & bushings','Track & suspension','High','Inspect play, tie rods and fasteners.'],
 ['Wiring, switches & grounds','Electrical','High','Inspect brittle wiring and grounds. Measure lighting voltage and identify installed charging components.'],
 ['Headlight assembly & mounting hardware','Electrical','High','Confirm lamp voltage, mounting hole, base and all fasteners. Early pedestal replacement lead is in the supplier directory.'],
 ['Taillight & lens','Electrical','Normal','Confirm lamp style and operating voltage.'],
 ['Hood assessment / fiberglass repair','Body & cosmetics','Normal','Match the existing hood before buying. Inspect cracks and mounting points.'],
 ['Seat cover, foam & base','Body & cosmetics','Normal','Inspect seat base and measure before selecting a cover.'],
 ['Windshield, trim & hardware','Body & cosmetics','Normal','Match hood, hole pattern, dimensions and trim.'],
 ['Decals, paint & body fasteners','Body & cosmetics','Cosmetic','Confirm chassis model/year before selecting model-specific decals.'],
 ['Throttle and brake cables','Cables & brakes','High','Inspect for fraying, corrosion and free movement; verify ends and lengths.'],
 ['Brake friction parts & return hardware','Cables & brakes','High','Identify installed brake assembly and inspect wear and reliable return.'],
 ['Fuel mixture & service-fluid specification','Research & setup','High','Verify premix ratio and chaincase fluid from the applicable operator manual and installed engine. No ratio assumed.']
];
const BUILT_IN_PHOTOS=[
 {id:'photo-front',sled:'early',title:'Front hood & windshield',src:'assets/IMG_6641.jpg'},
 {id:'photo-motor',sled:'early',title:'Rotax engine & serial plate',src:'assets/IMG_6642.jpg'},
 {id:'photo-chart',sled:'early',title:'Owner-supplied engine comparison chart',src:'assets/IMG_6644.jpg'},
 {id:'photo-eight-porch',sled:'eight',title:'1968 Ski-Doo on the porch',src:'assets/IMG_1299.jpg'},
 {id:'photo-eight-badge',sled:'eight',title:'Super Olympique E seat badge',src:'assets/IMG_4522.jpg'},
 {id:'photo-eight-plate',sled:'eight',title:'Chassis serial plate — as photographed',src:'assets/IMG_4523.jpg'}
];
function mergeBuiltInPhotos(saved){for(const p of BUILT_IN_PHOTOS)if(!saved.photos.some(x=>x.id===p.id||x.src===p.src))saved.photos.push({...p});return saved;}
function initialState(){const parts=[];for(const sled of ['early','eight'])baseParts.forEach((p,i)=>parts.push({id:`${sled}-${i}`,sled,name:p[0],category:p[1],priority:p[2],notes:p[3],status:'Inspect',qty:1,cost:0,number:'',url:''}));parts.push({id:'early-year',sled:'early',name:'Confirm chassis year & model',category:'Research & setup',priority:'High',notes:'Photograph full side, dashboard, chassis markings and carburetor tag. Engine serial alone does not date chassis.',status:'Needed',qty:1,cost:0,number:'',url:''},{id:'eight-plate',sled:'eight',name:'Review SE8 data plate & engine tag',category:'Research & setup',priority:'High',notes:'Plate photo is in the archive; supplied text says 3E8-131356; SE8 maps to a 1968 Olympique 300 E.',status:'Needed',qty:1,cost:0,number:'',url:''},{id:'eight-battery',sled:'eight',name:'Battery, starter & charging circuit',category:'Electrical',priority:'High',notes:'300 E is the electric-start model. Identify and test installed hardware; verify battery voltage before ordering.',status:'Inspect',qty:1,cost:0,number:'',url:''});return{schema:1,parts,logs:[{id:'log-early',sled:'early',date:'2026-10-18',title:'The identification puzzle',body:'Front and engine photos added. Early body style previously estimated as 1963–1965, but chassis year remains unconfirmed. Engine number appears to be 1308696. The supplied comparison chart suggests a 1967 engine; this is a lead, not proof of an engine swap.'},{id:'log-eight',sled:'eight',date:'2026-10-19',title:'1968 restoration file opened',body:'Imported the restoration brief. Model code SE8 is documented as the 1968 Olympique 300 E. The plate is currently a text transcription (3E8-131356), so identification remains provisional. Parts list converted into inspection and purchasing tasks; sizes and fluids are not assumed.'}],photos:BUILT_IN_PHOTOS.map(p=>({...p}))};}
let state;try{const saved=localStorage.getItem(KEY);state=saved?JSON.parse(saved):initialState();if(!validState(state))throw Error('invalid');mergeBuiltInPhotos(state);state.guides=Guide.migrate(state.guides,state);}catch{state=initialState();}
function validState(s){return s&&s.schema===1&&Array.isArray(s.parts)&&Array.isArray(s.logs)&&Array.isArray(s.photos)&&s.parts.every(p=>p&&typeof p.id==='string'&&['early','eight'].includes(p.sled)&&typeof p.name==='string'&&CATEGORIES.includes(p.category)&&STATUSES.includes(p.status)&&Number.isFinite(Number(p.cost))&&Number(p.cost)>=0&&Number.isFinite(Number(p.qty))&&Number(p.qty)>0)&&s.logs.every(x=>x&&typeof x.id==='string'&&['early','eight'].includes(x.sled)&&typeof x.title==='string'&&typeof x.body==='string'&&/^\d{4}-\d{2}-\d{2}$/.test(x.date))&&s.photos.every(x=>x&&typeof x.id==='string'&&['early','eight'].includes(x.sled)&&typeof x.title==='string'&&typeof x.src==='string'&&(BUILT_IN_PHOTOS.some(p=>p.src===x.src)||/^data:image\/(jpeg|png|webp);base64,/.test(x.src)));}
function persist(){try{localStorage.setItem(KEY,JSON.stringify(state));return true}catch{toast('Storage is full or unavailable. Export a backup now.');return false}}
function toast(message){const t=document.querySelector('#toast');t.textContent=message;t.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>t.classList.remove('show'),4500)}
const safeURL=x=>{try{const u=new URL(x);return ['https:','http:'].includes(u.protocol)?u.href:''}catch{return''}};
const fmtSled=s=>s==='early'?'EARLY SKI-DOO':'1968 · 300 E';

function progress(sled){const ps=state.parts.filter(p=>p.sled===sled&&p.status!=='Not required');return{done:ps.filter(p=>p.status==='Installed').length,total:ps.length,percent:ps.length?Math.round(ps.filter(p=>p.status==='Installed').length/ps.length*100):0}}
function stats(){return `<div class="stats"><div class="stat"><small>In the collection</small><strong>02</strong><span>Vintage Ski-Doos</span></div><div class="stat"><small>Parts to assess</small><strong>${state.parts.filter(p=>p.status==='Inspect'||p.status==='Needed').length}</strong><span>Inspect or identify first</span></div><div class="stat"><small>Parts installed</small><strong>${state.parts.filter(p=>p.status==='Installed').length}</strong><span>Every small win counts</span></div><div class="stat"><small>Recorded spend</small><strong>${money(state.parts.reduce((a,p)=>a+Number(p.cost||0),0))}</strong><span>Actual recorded line totals</span></div></div>`}
function card(s){const p=progress(s);return `<article class="sled-card"><div class="sled-visual">${s==='early'?'<img src="assets/IMG_6641.jpg" alt="Joshua’s early yellow Ski-Doo, photographed from the front">':'<img class="sled-photo-eight" src="assets/IMG_1299.jpg" alt="The 1968 yellow Ski-Doo on the porch">'}<span class="sled-number">COLLECTION / ${s==='early'?'01':'02'}</span></div><div class="sled-body"><div class="sled-title"><div><h3>${esc(guideSledTitle(s))}</h3><p class="model">${esc(guideIdentityCaption(s))}</p></div><span class="badge amber">${esc(guideIdentityBadge(s))}</span></div><p class="description">${s==='early'?'A familiar yellow hood. An engine number from a different era. The chassis story is still being uncovered.':'The electric-start chapter. A 300 cc class restoration guided by factory documents and the installed hardware.'}</p><div class="mini-specs"><div><small>ENGINE</small><b>${s==='early'?'247 cc on tag':'300 cc class¹'}</b></div><div><small>IDENTITY</small><b>${s==='early'?'Chassis unresolved':'SE8, if confirmed¹'}</b></div><div><small>PROJECT</small><b>${esc(Guide.summary(state,s).phase?.title||'Complete')}</b></div></div><div class="progress-line"><span>RESTORATION PROGRESS</span><span>${p.percent}%</span></div><div class="progress"><i style="width:${p.percent}%"></i></div><div class="card-bottom"><span class="muted">${p.done} of ${p.total} tasks installed</span><button data-guide-sled="${s}">Next restoration step ↗</button></div></div></article>`}
function head(eye,title,desc,button=''){return `<div class="page-head"><div><span class="eyebrow muted">${eye}</span><h1>${title}</h1><p>${desc}</p></div>${button}</div>`}
function mobileData(){return `<div class="mobile-data"><button data-action="backup">Export backup ↗</button><button data-action="restore">Import backup</button></div><p class="mini-note">Parts, journal entries and added photos save in this browser. Export a backup to keep a copy or move to another device.</p>`}
function overview(){return `${head('TWO MACHINES. ONE WORK IN PROGRESS.','Back in the garage.','The history, the parts, and everything between the first pull and the first ride.',`<button class="button secondary" data-add-log>+ Add workshop note</button>`)}${guideDashboard()}<section class="hero"><div class="hero-copy"><span class="eyebrow">THE TOBIN COLLECTION / 01—02</span><h1>BUILT FOR SNOW.<br>KEPT FOR<br>THE STORIES.</h1><p>A home for two vintage Ski-Doos—and the work that brings them back.</p><button class="button dark" data-nav="guide">Continue guided restoration <span>↗</span></button></div><div class="hero-picture"><img src="assets/IMG_6641.jpg" alt="The early yellow Ski-Doo in Joshua’s driveway"><div class="photo-label"><div>FROM THE CAMERA ROLL<b>The early one.</b></div><span>01</span></div></div></section>${stats()}<section><div class="section-head"><h2>Two sleds. Two stories.</h2><button data-nav="sleds">Explore the collection ↗</button></div><div class="fleet">${card('early')}${card('eight')}</div></section><div class="overview-bottom">${guideNextOnBench()}<section class="panel note-panel"><span class="eyebrow">RESEARCH NOTE / 001</span><h3>A year is more than<br>an engine number.</h3><p>The early sled’s engine tag appears to read 1308696. Your comparison chart suggests a 1967 engine, while the body appears earlier. A swap is possible; the chassis year remains unconfirmed.</p><button class="button secondary small" data-profile="early">Read the identification notes ↗</button></section></div>${mobileData()}`}
let selectedSled='early',partSearch='',partSled='all',partCategory='all',partStatus='all',journalSled='all',photoSled='all';
function profiles(){const s=selectedSled,p=progress(s);return `${head('THE COLLECTION','The sled files.','One place for the identity, evidence and restoration plan of each machine.')}<div class="pill-tabs"><button data-profile="early" class="${s==='early'?'active':''}">01 · Early Ski-Doo</button><button data-profile="eight" class="${s==='eight'?'active':''}">02 · 1968 Olympique</button></div>${guideSledPrompt(s)}<section class="profile">${s==='early'?'<img class="profile-img" src="assets/IMG_6641.jpg" alt="Early yellow Ski-Doo">':'<img class="profile-img profile-photo-eight" src="assets/IMG_1299.jpg" alt="1968 yellow Ski-Doo photographed on the porch">'}<div class="profile-info"><span class="badge amber">${esc(guideIdentityBadge(s))}</span><h2>${esc(guideSledTitle(s))}</h2><p>${recordedChassis(s)?'Identification and source recorded in the guided walkthrough.':s==='early'?'Working label only. Visual estimate: 1963–1965.':'Probable SE8 model. Also called Super-Olympique E in the 1968 parts manual.¹'}</p><div class="spec-table">${(guideProfileSpecs(s)||(s==='early'?[['Chassis identity','Unconfirmed — no chassis plate supplied'],['Engine tag','1308696 (photo transcription)'],['Displacement','247 cc shown on engine tag'],['Engine year lead','1967, per owner-supplied chart'],['Bodywork','Fiberglass hood; metal tunnel'],['Engine swap','Possible; not established']]:[['Plate transcription','3E8-131356 (owner-provided text)'],['Expected model code','SE8 — compare with the supplied plate¹'],['Factory model','Olympique 300 E / Super-Olympique E¹'],['Factory engine class','300 cc single; verify installed engine¹'],['Factory output','16 HP for SE8¹'],['Starting','Electric-start model¹']])).map(x=>`<div class="spec-row"><span>${x[0]}</span><b>${esc(x[1])}</b></div>`).join('')}</div></div></section><div class="research-grid"><section class="panel"><h3>What would confirm it?</h3><ul>${s==='early'?'<li>A clear full side view and dashboard photo.</li><li>Any surviving chassis tag or stamped numbers.</li><li>Installed engine and carburetor markings.</li><li>Compare chassis details against factory parts diagrams.</li>':'<li>The supplied chassis plate photo is in Photos & manuals.</li><li>Check S versus 3 in the first character of the model code.</li><li>Photograph the installed engine tag and carburetor stamping.</li><li>Confirm starter and charging components are present.</li>'}</ul><button class="button secondary small" style="margin-top:18px" data-add-photo>+ Add evidence photo</button></section><section class="panel note-panel"><h3>${s==='early'?'Keep engine and chassis separate.':'The old parts list needed a correction.'}</h3><p>${s==='early'?'A later engine in an earlier chassis is plausible. The comparison chart is a research lead, not a chassis certificate. Do not order a 1967 hood on the strength of the engine number alone.':'The factory parts table specifies a 76.00 mm standard piston for the 300/300E; the pasted 69 mm size belongs to the 250. Measure the actual cylinder before selecting parts. Oil ratio, fluids, belt specification and battery voltage still need verification.¹'}</p><p style="margin-top:12px">${s==='early'?`<a class="source-link" href="${sourceEarly}" target="_blank" rel="noopener">1960–1965 factory parts reference ↗</a>`:`<a class="source-link" href="${source68}" target="_blank" rel="noopener">¹ 1968 factory parts reference ↗</a> · <a class="source-link" href="${sourceCodes}#page=17" target="_blank" rel="noopener">Model-code table ↗</a>`}</p></section></div><section class="panel" style="margin-top:24px"><div class="section-head"><h3>Restoration progress</h3><button data-sled-parts="${s}">See this sled’s parts ↗</button></div><div class="progress-line"><span>${p.done} installed / ${p.total} active items</span><span>${p.percent}%</span></div><div class="progress"><i style="width:${p.percent}%"></i></div><p class="mini-note">Progress counts installed items; “Not required” items are excluded. No work has been assumed complete.</p></section>`}
const option=(v,label,selected)=>`<option value="${esc(v)}"${v===selected?' selected':''}>${esc(label)}</option>`;
function parts(){return `${head('RESTORATION / INVENTORY','Parts & purchases.','Inspect first. Confirm fitment. Keep the receipts together.',`<button class="button" data-add-part>+ Add part</button>`)}<div class="banner"><b>The guide turns this list into a restoration plan.</b><button class="text-button" data-nav="guide">Open your next guided action ↗</button>The imported list is organized by system. Quantities default to one tracked task, not a confirmed replacement count. Measure and identify components before ordering.</div>${['early','eight'].map(sled=>`<section class="parts-identity"><span class="eyebrow muted">${esc(NAMES[sled])}</span>${guideOrderingStatus(sled)}</section>`).join('')}${stats()}<div class="filterbar"><input type="search" id="part-search" placeholder="Search parts, notes or part numbers…" aria-label="Search parts" value="${esc(partSearch)}"><select id="part-sled" aria-label="Filter by sled">${option('all','Both sleds',partSled)}${Object.entries(NAMES).map(([k,v])=>option(k,v,partSled)).join('')}</select><select id="part-category" aria-label="Filter by system">${option('all','All systems',partCategory)}${CATEGORIES.map(c=>option(c,c,partCategory)).join('')}</select><select id="part-status" aria-label="Filter by status">${option('all','All statuses',partStatus)}${STATUSES.map(c=>option(c,c,partStatus)).join('')}</select></div><div class="section-head"><span id="part-count" class="eyebrow muted"></span><button data-export-csv>Export parts CSV ↗</button></div><div class="table-wrap"><table><thead><tr><th>Part / task</th><th>Sled & system</th><th>Status</th><th>Qty</th><th>Actual total</th><th>Details</th></tr></thead><tbody id="part-rows"></tbody></table></div>${mobileData()}`}
function filteredParts(){const q=partSearch.toLowerCase();return state.parts.filter(p=>(partSled==='all'||p.sled===partSled)&&(partCategory==='all'||p.category===partCategory)&&(partStatus==='all'||p.status===partStatus)&&[p.name,p.notes,p.number].join(' ').toLowerCase().includes(q))}
function updateRows(){const list=filteredParts();document.querySelector('#part-count').textContent=`${list.length} OF ${state.parts.length} ITEMS`;document.querySelector('#part-rows').innerHTML=list.length?list.map(p=>`<tr><td><div class="part-name">${esc(p.name)}</div><div class="part-note">${esc(p.notes)}</div><small>${p.number?'Part # '+esc(p.number):'Part number / fitment pending'}</small></td><td><span class="badge ${p.sled==='early'?'amber':'green'}">${fmtSled(p.sled)}</span><br><small>${esc(p.category)} · ${esc(p.priority)}</small></td><td><select aria-label="Status for ${esc(p.name)} (${esc(NAMES[p.sled])})" data-part-status="${esc(p.id)}">${STATUSES.map(x=>option(x,x,p.status)).join('')}</select></td><td>${esc(p.qty)}</td><td>${money(p.cost)}</td><td><div class="part-actions"><button class="icon-btn" data-edit-part="${esc(p.id)}">Edit</button>${safeURL(p.url)?`<a class="icon-btn" href="${esc(safeURL(p.url))}" target="_blank" rel="noopener">Link ↗</a>`:''}</div></td></tr>`).join(''):'<tr><td colspan="6" class="empty">No matching parts. Change a filter or add a part.</td></tr>'}
function journal(){const logs=state.logs.filter(l=>journalSled==='all'||l.sled===journalSled).slice().sort((a,b)=>b.date.localeCompare(a.date));return `${head('NOTES FROM THE BENCH','Workshop journal.','Keep the discoveries, measurements and small victories.',`<button class="button" data-add-log>+ Add note</button>`)}<div class="filterbar"><select id="journal-sled" aria-label="Filter journal by sled">${option('all','Both sleds',journalSled)}${Object.entries(NAMES).map(([k,v])=>option(k,v,journalSled)).join('')}</select></div><div class="journal-grid">${logs.length?logs.map(l=>`<article class="journal-card"><div class="journal-meta"><span class="badge ${l.sled==='early'?'amber':'green'}">${fmtSled(l.sled)}</span><span>${dateLabel(l.date)}</span></div><h3>${esc(l.title)}</h3><p>${esc(l.body)}</p><div class="part-actions"><button class="icon-btn" data-edit-log="${esc(l.id)}">Edit note</button><button class="icon-btn" data-delete-log="${esc(l.id)}">Delete</button></div></article>`).join(''):'<div class="empty"><h3>A fresh page.</h3>Add your first workshop note for this sled.</div>'}</div>${mobileData()}`}
const resources=[['FACTORY / 1960–1965','Early Ski-Doo parts manual','Original assembly diagrams and part lists. Chassis year still needs confirmation.',sourceEarly],['FACTORY / 1968','1968 parts manual','250 / 300 / 300E assemblies. Match the correct model column.',source68],['FACTORY / MODEL CODES','Historical model-code table','1997 booklet includes early Ski-Doo model identification. SE8 entry on PDF page 17.',sourceCodes+'#page=17'],['MUSEUM / ORIGINAL DOCUMENTS','J. Armand Bombardier archive','Technical manuals, brochures and historical resources.','https://museebombardier.com/en/services/'],['FACTORY / PERIOD BROCHURE','1968 Ski-Doo sales brochure','French-language factory brochure hosted by the Bombardier museum.','https://museebombardier.com/wp-content/uploads/2020/04/Brochure_vente_Ski_Doo_Alpine_Olympique_1968_fr.pdf'],['FACTORY / CONSOLIDATED','1960–1969 parts catalogue','Museum-hosted consolidated original parts reference.','https://museebombardier.com/wp-content/uploads/2020/04/Catalogue_pieces_Ski_Doo_1960_1969.pdf']];
const suppliers=[['FIBERGLASS / SUPPLIER LEAD','Henning Fiberglass','Vintage reproduction parts and repair. Exact early hood availability is unconfirmed.','https://www.henningfiberglass.com/ski-doo-vintage-snowmobile'],['LIGHTING / REPLACEMENT LEAD','Early pedestal headlight','Seller advertises 1963–1965 replacement. Not an exact original. Verify voltage, fit and nut/washer inclusion. Price and availability may change.','https://www.ebay.com/itm/392272294241'],['DECALS / YEAR MUST MATCH','DooDecals','Vintage graphics and restoration references. Confirm chassis model before buying.','https://skidoodecals.afegraphics.com/'],['USED & NOS / SUPPLIER LEAD','Al’s Snowmobile Parts','Search by verified part number. No specific inventory or fitment assumed.','https://alssnowmobile.com/']];
function resourceCards(list){return list.map(r=>`<a class="resource" href="${esc(r[3])}" target="_blank" rel="noopener"><div><small>${r[0]}</small><h4>${r[1]}</h4><p>${r[2]}</p></div><span>↗</span></a>`).join('')}
function archive(){const photos=state.photos.filter(p=>photoSled==='all'||p.sled===photoSled);return `${head('THE REFERENCE SHELF','Photos & manuals.','Original evidence, factory documents and useful supplier leads.',`<button class="button" data-add-photo>+ Add photo</button>`)}<div class="section-head"><h2>From the camera roll</h2><select id="photo-sled" aria-label="Filter photos by sled">${option('all','Both sleds',photoSled)}${Object.entries(NAMES).map(([k,v])=>option(k,v,photoSled)).join('')}</select></div>${photos.length?`<div class="gallery">${photos.map(p=>`<figure><button data-photo="${esc(p.id)}" aria-label="View ${esc(p.title)}"><img src="${esc(p.src)}" alt="${esc(p.title)}" loading="lazy"></button><figcaption><span>${esc(p.title)}</span>${p.src.startsWith('data:')?`<button class="icon-btn" data-delete-photo="${esc(p.id)}" aria-label="Delete ${esc(p.title)}">×</button>`:'<span>↗</span>'}</figcaption></figure>`).join('')}</div>`:'<div class="empty"><h3>No photos for this sled yet.</h3>Add the data plate, engine tag and a full side view.</div>'}<section class="archive-section"><div class="section-head"><h2>Factory documents</h2><span class="eyebrow muted">PRIMARY SOURCES</span></div><div class="resources">${resourceCards(resources)}</div></section><section class="archive-section"><div class="section-head"><h2>The parts counter</h2><span class="eyebrow muted">FITMENT TO VERIFY</span></div><div class="resources">${resourceCards(suppliers)}</div></section><section class="panel note-panel" style="margin-top:24px"><h3>Source notes</h3><p style="margin-top:12px;font-size:11px">¹ Factory references support SE8 → 1968 Olympique 300 E (16 HP), electric start, and the 76.00 mm standard piston for the 300/300E. They do not verify the currently installed engine or the transcribed plate. Early engine-year chart is owner-supplied and not a factory chassis identifier. Supplier links are leads, not guaranteed compatibility or current stock.</p></section>${mobileData()}`}
let currentView='overview';
const labels={guide:'Guided restoration',overview:'Overview',sleds:'The sleds',parts:'Parts & purchases',journal:'Workshop journal',archive:'Photos & manuals'};
function render(view=currentView){currentView=Object.hasOwn(labels,view)?view:'overview';document.querySelector('#main').innerHTML=({guide:guideView,overview,sleds:profiles,parts,journal,archive})[currentView]();document.querySelector('#breadcrumb').textContent=labels[currentView];document.querySelectorAll('nav button').forEach(b=>{b.classList.toggle('active',b.dataset.view===currentView);if(b.dataset.view===currentView)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current')});if(currentView==='parts')updateRows();}
function navigate(view){if(location.hash.slice(1)===view)render(view);else location.hash=view;window.scrollTo({top:0,behavior:'smooth'})}
window.addEventListener('hashchange',()=>render(location.hash.slice(1)));
function field(name,label,value='',type='text',extra=''){return `<div class="field"><label for="f-${name}">${label}</label><input id="f-${name}" name="${name}" type="${type}" value="${esc(value)}" ${extra}></div>`}
function selectField(name,label,values,value){return `<div class="field"><label for="f-${name}">${label}</label><select id="f-${name}" name="${name}">${values.map(x=>option(Array.isArray(x)?x[0]:x,Array.isArray(x)?x[1]:x,value)).join('')}</select></div>`}
function textarea(name,label,value=''){return `<div class="field"><label for="f-${name}">${label}</label><textarea id="f-${name}" name="${name}">${esc(value)}</textarea></div>`}
let editing={};
function openEditor(type,id){editing={type,id};const p=(type==='part'?state.parts:type==='log'?state.logs:[]).find(x=>x.id===id)||{};document.querySelector('#dialog-title').textContent=type==='part'?(id?'Edit part / task':'Add a part / task'):type==='log'?(id?'Edit workshop note':'Add a workshop note'):'Add an evidence photo';document.querySelector('#dialog-kind').textContent=type==='part'?'PARTS COUNTER':type==='log'?'WORKSHOP JOURNAL':'PHOTO ARCHIVE';const sledSelect=selectField('sled','Sled',Object.entries(NAMES),p.sled||(currentView==='sleds'?selectedSled:partSled!=='all'?partSled:'early'));document.querySelector('#dialog-fields').innerHTML=type==='part'?`${field('name','Part / task name',p.name,'text','required maxlength="180"')}${sledSelect}<div class="field-pair">${selectField('category','System',CATEGORIES,p.category||CATEGORIES[0])}${selectField('priority','Priority',['High','Normal','Cosmetic'],p.priority||'Normal')}</div><div class="field-pair">${selectField('status','Status',STATUSES,p.status||'Inspect')}${field('qty','Quantity / task count',p.qty||1,'number','required min="1" max="10000" step="1"')}</div><div class="field-pair">${field('number','Verified part number',p.number)}${field('cost','Actual line total ($)',p.cost||0,'number','required min="0" max="1000000" step="0.01"')}</div>${field('url','Supplier / receipt URL',p.url,'url')}${textarea('notes','Measurements, fitment & notes',p.notes)}<p class="mini-note">Actual total is the full cost for this row, including its quantity. Use $0 until an actual cost is recorded.</p>${id?`<button type="button" class="text-button" data-delete-part="${esc(id)}">Delete this item</button>`:''}`:type==='log'?`${field('title','Note title',p.title,'text','required maxlength="180"')}<div class="field-pair">${sledSelect}${field('date','Date',p.date||today(),'date','required')}</div>${textarea('body','Workshop notes',p.body)}`:`${sledSelect}${field('title','Photo title','','text','required maxlength="180"')}<div class="field"><label for="f-file">Choose a photo</label><input type="file" id="f-file" name="photo" accept="image/jpeg,image/png,image/webp" required><small>JPEG, PNG or WebP. Photos are resized and saved in this browser. Export a backup to keep them.</small></div>`;document.querySelector('#editor').showModal();}
function download(name,content,type){const u=URL.createObjectURL(new Blob([content],{type}));const a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)}
function backup(){download(`tobin-skidoo-backup-${today()}.json`,JSON.stringify(state,null,2),'application/json');toast('Backup exported. Keep it somewhere safe.');}
function exportCSV(){const lines=[['Sled','Part / task','System','Priority','Status','Quantity','Actual line total USD','Part number','Supplier URL','Notes'],...filteredParts().map(p=>[NAMES[p.sled],p.name,p.category,p.priority,p.status,p.qty,p.cost,p.number,p.url,p.notes])];download('tobin-skidoo-parts.csv',lines.map(row=>row.map(v=>'"'+String(v??'').replace(/^[=+@\-]/,"'$&").replace(/"/g,'""')+'"').join(',')).join('\r\n'),'text/csv;charset=utf-8');toast('Filtered parts exported as CSV.');}
async function imageData(file){if(file.size>20*1024*1024)throw Error('Please choose an image smaller than 20 MB.');const blob=await createImageBitmap(file);const scale=Math.min(1,1200/Math.max(blob.width,blob.height));const c=document.createElement('canvas');c.width=Math.round(blob.width*scale);c.height=Math.round(blob.height*scale);c.getContext('2d').drawImage(blob,0,0,c.width,c.height);blob.close();return c.toDataURL('image/jpeg',.78)}
document.querySelector('#editor-form').addEventListener('submit',async e=>{e.preventDefault();const form=e.currentTarget,d=Object.fromEntries(new FormData(form));const submit=form.querySelector('[type="submit"]');submit.disabled=true;try{if(editing.type==='part'){const p={id:editing.id||uid(),sled:d.sled,name:d.name.trim(),category:d.category,priority:d.priority,status:d.status,qty:Number(d.qty),cost:Number(d.cost),number:d.number.trim(),url:d.url.trim(),notes:d.notes.trim()};if(!p.name)throw Error('Add a part name.');if(p.url&&!safeURL(p.url))throw Error('Use an http or https supplier link.');const before=state.parts.find(x=>x.id===editing.id);const gate=guidePurchaseErrors(p,p.status);if(gate.length&&(before?.status!==p.status||before?.sled!==p.sled))throw Error('Before ordering: '+gate[0]);if(editing.id)state.parts=state.parts.map(x=>x.id===editing.id?p:x);else state.parts.push(p);}else if(editing.type==='log'){if(!d.title.trim())throw Error('Add a note title.');const l={id:editing.id||uid(),sled:d.sled,date:d.date,title:d.title.trim(),body:d.body.trim()};if(editing.id)state.logs=state.logs.map(x=>x.id===editing.id?l:x);else state.logs.push(l);}else{const file=form.querySelector('#f-file').files[0];const src=await imageData(file);const p={id:uid(),sled:d.sled,title:d.title.trim(),src};state.photos.push(p);if(!persist()){state.photos.pop();throw Error('Photo could not be saved. Export a backup or remove an added photo first.');}}const saved=persist();document.querySelector('#editor').close();render();if(saved)toast('Saved to this browser.');}catch(error){toast(error.message)}finally{submit.disabled=false}});
document.addEventListener('click',e=>{const b=e.target.closest('button,a');if(!b)return;if(b.matches('.close')){b.closest('dialog').close();return}if(b.dataset.view||b.dataset.nav){navigate(b.dataset.view||b.dataset.nav);return}if(b.dataset.profile){selectedSled=b.dataset.profile;navigate('sleds');return}if(b.dataset.sledParts){partSled=b.dataset.sledParts;partSearch='';partCategory='all';partStatus='all';navigate('parts');return}if(b.hasAttribute('data-add-part'))openEditor('part');if(b.dataset.editPart)openEditor('part',b.dataset.editPart);if(b.hasAttribute('data-add-log'))openEditor('log');if(b.dataset.editLog)openEditor('log',b.dataset.editLog);if(b.hasAttribute('data-add-photo'))openEditor('photo');if(b.dataset.photo){const p=state.photos.find(x=>x.id===b.dataset.photo);const dialog=document.querySelector('#photo-dialog');dialog.querySelector('img').src=p.src;dialog.querySelector('img').alt=p.title;dialog.querySelector('p').textContent=p.title;dialog.showModal();}for(const [attr,key] of [['deletePart','parts'],['deleteLog','logs'],['deletePhoto','photos']])if(b.dataset[attr]&&confirm('Delete this item? This cannot be undone without a backup.')){state[key]=state[key].filter(x=>x.id!==b.dataset[attr]);persist();if(document.querySelector('#editor').open)document.querySelector('#editor').close();render();toast('Item deleted.');}if(b.hasAttribute('data-export-csv'))exportCSV();if(b.id==='backup'||b.dataset.action==='backup')backup();if(b.id==='restore'||b.dataset.action==='restore')document.querySelector('#restore-file').click();});
document.addEventListener('input',e=>{if(e.target.id==='part-search'){partSearch=e.target.value;updateRows()}});
document.addEventListener('change',e=>{const t=e.target;if(t.dataset.partStatus){const p=state.parts.find(x=>x.id===t.dataset.partStatus);const gate=guidePurchaseErrors(p,t.value);if(gate.length&&p.status!==t.value){t.value=p.status;showPurchaseGate(p,gate);return;}p.status=t.value;persist();render();toast('Part status updated.');return}if(t.id==='part-sled'){partSled=t.value;updateRows()}if(t.id==='part-category'){partCategory=t.value;updateRows()}if(t.id==='part-status'){partStatus=t.value;updateRows()}if(t.id==='journal-sled'){journalSled=t.value;render()}if(t.id==='photo-sled'){photoSled=t.value;render()}});
document.querySelector('#restore-file').addEventListener('change',async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>12*1024*1024)throw Error('Backup is too large (12 MB maximum).');const next=JSON.parse(await file.text());if(!validState(next))throw Error('This is not a valid garage backup.');if(!confirm('Replace the current browser data with this backup? Export the current data first if needed.'))return;const previous=state;state=mergeBuiltInPhotos(next);state.guides=Guide.migrate(state.guides,state);if(!persist()){state=previous;throw Error('Backup could not be saved in this browser.');}render();toast('Backup imported.');}catch(error){toast(error.message||'Could not read backup.')}finally{e.target.value=''}});
render(location.hash.slice(1)||'overview');
